import crypto from 'node:crypto';
import { db } from '../db';

export interface User {
  id: number;
  username: string;
}

export function createSession(userId: number): string {
  const sessionId = crypto.randomBytes(32).toString('hex');
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(); // 24 hours

  const stmt = db.prepare('INSERT INTO sessions (id, user_id, expires_at) VALUES (?, ?, ?)');
  stmt.run(sessionId, userId, expiresAt);

  return sessionId;
}

export function validateSession(sessionId: string | undefined): User | null {
  if (!sessionId) return null;

  const stmt = db.prepare(`
    SELECT users.id, users.username, sessions.expires_at 
    FROM sessions 
    JOIN users ON sessions.user_id = users.id 
    WHERE sessions.id = ?
  `);

  const row = stmt.get(sessionId) as { id: number; username: string; expires_at: string } | undefined;

  if (!row) return null;

  // Check if expired
  if (new Date(row.expires_at).getTime() < Date.now()) {
    deleteSession(sessionId);
    return null;
  }

  return {
    id: row.id,
    username: row.username,
  };
}

export function deleteSession(sessionId: string): void {
  const stmt = db.prepare('DELETE FROM sessions WHERE id = ?');
  stmt.run(sessionId);
}

import { createServerFn } from '@tanstack/react-start';

const COOKIE_NAME = 'session_id';
const COOKIE_OPTIONS = {
  httpOnly: true,
  path: '/',
  sameSite: 'lax' as const,
  secure: false,
  maxAge: 24 * 60 * 60, // 24 hours
};

export const getCurrentUser = createServerFn({ method: 'GET' })
  .handler(async () => {
    const { getCookie } = await import('@tanstack/react-start/server');
    const { validateSession } = await import('./auth.server');

    const sessionId = getCookie(COOKIE_NAME);
    return validateSession(sessionId);
  });

export const registerUser = createServerFn({ method: 'POST' })
  .validator((data: any) => {
    if (!data || typeof data.username !== 'string' || typeof data.password !== 'string') {
      throw new Error('Invalid input');
    }
    return data as { username: string; password: string };
  })
  .handler(async ({ data }) => {
    const { username, password } = data;
    const { db } = await import('../db');
    const { hashPassword } = await import('./crypto');
    const { createSession } = await import('./auth.server');
    const { setCookie } = await import('@tanstack/react-start/server');

    const trimmedUsername = username.trim();
    if (!trimmedUsername || password.length < 1) {
      throw new Error('Username and password are required');
    }

    // Check if username already exists
    const existing = db.prepare('SELECT id FROM users WHERE username = ?').get(trimmedUsername);
    if (existing) {
      throw new Error('Username already taken');
    }

    // Hash password and insert
    const passwordHash = hashPassword(password);
    const result = db.prepare('INSERT INTO users (username, password_hash) VALUES (?, ?)')
      .run(trimmedUsername, passwordHash);

    const userId = Number(result.lastInsertRowid);

    // Create session
    const sessionId = createSession(userId);

    // Set cookie
    setCookie(COOKIE_NAME, sessionId, COOKIE_OPTIONS);

    return { success: true };
  });

