import { db } from './src/db/index.ts';
import { hashPassword, verifyPassword } from './src/utils/crypto.ts';
import { createSession, validateSession, deleteSession } from './src/utils/auth.server.ts';

async function test() {
  console.log('Starting authentication tests...');

  // 1. Test Password Hashing
  const password = 'mySecretPassword123';
  const hashed = hashPassword(password);
  console.log('Hashed Password:', hashed);

  const isMatch = verifyPassword(password, hashed);
  console.log('Password verification match:', isMatch);
  if (!isMatch) throw new Error('Password verification failed!');

  const isNotMatch = verifyPassword('wrongpassword', hashed);
  console.log('Password verification wrong match (should be false):', isNotMatch);
  if (isNotMatch) throw new Error('Password verification succeeded for wrong password!');

  // 2. Test Database & Sessions
  // Clear tables
  db.exec('DELETE FROM sessions');
  db.exec('DELETE FROM users');

  // Insert test user
  const username = 'testuser';
  const insertUser = db.prepare('INSERT INTO users (username, password_hash) VALUES (?, ?)');
  const result = insertUser.run(username, hashed);
  const userId = Number(result.lastInsertRowid);
  console.log('Inserted test user ID:', userId);

  // Create session
  const sessionId = createSession(userId);
  console.log('Created session ID:', sessionId);

  // Validate session
  const validatedUser = validateSession(sessionId);
  console.log('Validated session user:', validatedUser);
  if (!validatedUser || validatedUser.username !== username) {
    throw new Error('Session validation failed!');
  }

  // Delete session
  deleteSession(sessionId);
  const validatedUserAfterDelete = validateSession(sessionId);
  console.log('Validated session after delete (should be null):', validatedUserAfterDelete);
  if (validatedUserAfterDelete !== null) {
    throw new Error('Session deletion failed, still validated!');
  }

  console.log('All tests passed successfully! Authentication logic is robust and correct.');
}

test().catch(err => {
  console.error('Test failed:', err);
  process.exit(1);
});
